import {esc} from '../config.mjs';
export async function renderRecovery(app,call,onBack){
 app.innerHTML='<div class="empty">Consultando recuperação financeira…</div>';
 try{const d=await call('admin.reconciliation',{});app.innerHTML=`<section><h1>Recuperação financeira</h1><p>Consultas agendadas procuram confirmações que não chegaram pelo webhook. Não criam cobranças nem confirmam por declaração do cliente. Pendências após sete dias exigem conferência.</p><button class="btn secondary" id="recovery-back">Voltar</button><div class="orders">${(d.jobs||[]).map(j=>`<article class="order"><strong>${esc(j.code)} · ${esc(j.kind)}</strong><p>${esc(j.status)} · ${Number(j.attempts)} tentativas</p><p>${esc(j.last_error||'Aguardando próxima consulta ao provedor.')}</p><small>Próxima tentativa: ${esc(j.next_attempt_at?new Date(j.next_attempt_at).toLocaleString('pt-BR'):'—')}</small></article>`).join('')||'<p>Sem pendências nesta consulta.</p>'}</div></section>`;app.querySelector('#recovery-back').onclick=onBack}catch(e){app.innerHTML=`<p class="error">${esc(e.message)}</p><button id="recovery-back" class="btn secondary">Voltar</button>`;app.querySelector('#recovery-back').onclick=onBack}
}
export async function renderCities(app,call,onBack){
 app.innerHTML='<div class="empty">Consultando expansão por cidades…</div>';
 try{
  const d=await call('admin.geo',{}),rows=d.cities||[],status={observing:'Em observação',ready:'Critério atingido',review:'Em análise',open:'Inscrições abertas',paused:'Inscrições pausadas'};
  app.innerHTML=`<section><div class="eyebrow">Equipe HOCCO · informação interna</div><h1>Expansão por cidades</h1><p>Alerta quando há pelo menos 100 visitas deduplicadas por dia durante seis dias completos consecutivos, no horário de Brasília. Estimativa por IP; não equivale a pessoas ou moradores confirmados. Atualizações da página no mesmo navegador e dia não somam outra visita.</p><div class="actions"><button class="btn secondary" id="cities-back">Voltar ao administrativo</button><button class="btn secondary" id="cities-refresh">Atualizar</button></div><form id="cities-add" class="paper"><h2>Gerenciar outra cidade</h2><label for="cities-name">Cidade</label><input id="cities-name" name="city" maxlength="80" required><label for="cities-uf">UF</label><select id="cities-uf" name="uf">${'AC AL AP AM BA CE DF ES GO MA MT MS MG PA PB PR PE PI RJ RN RS RO RR SC SP SE TO'.split(' ').map(x=>`<option>${x}</option>`).join('')}</select><button class="btn secondary" type="submit">Colocar em observação</button></form><p class="error" id="cities-error" role="alert"></p><div class="orders">${rows.map(c=>`<article class="order"><h2>${esc(c.city)} · ${esc(c.state_code)}</h2><span class="badge ${c.status==='ready'?'orange':c.status==='open'?'success':''}">${esc(status[c.status]||c.status)}</span><p>${Number(c.visits_7d||0)} visitas nos últimos 7 dias · ${Number(c.visits_30d||0)} nos últimos 30 dias</p><p>${Number(c.active_sponsors||0)} empresas ativas · limite de 50 por cidade</p>${c.qualified_on?`<p>Critério de audiência atingido em ${esc(c.qualified_on)}. Abertura depende de decisão da equipe.</p>`:''}<details><summary>Contagens diárias</summary><p>${(c.daily||[]).map(x=>`${esc(x.day)}: ${Number(x.total)}`).join(' · ')||'Sem visitas registradas.'}</p></details><div class="actions">${[['review','Analisar cidade'],['open','Abrir inscrições'],['paused','Pausar inscrições'],['observing','Manter em observação']].map(([s,label])=>`<button type="button" class="btn secondary small" data-city="${esc(c.city)}" data-uf="${esc(c.state_code)}" data-status="${s}">${label}</button>`).join('')}</div></article>`).join('')||'<div class="empty">As contagens começam nesta atualização. Nenhuma cidade registrada ainda.</div>'}</div><p class="hint">VPN, operadoras móveis, limpeza do navegador e tráfego automatizado podem afetar as estimativas. O sistema filtra sinais comuns de robôs, mas não certifica audiência. Não abre cidades automaticamente.</p></section>`;
  app.querySelector('#cities-back').onclick=onBack;app.querySelector('#cities-refresh').onclick=()=>renderCities(app,call,onBack);
  const save=async(city,uf,status)=>{await call('admin.geo.mutate',{city,uf,status});await renderCities(app,call,onBack)};
  app.querySelectorAll('[data-city]').forEach(b=>b.onclick=async()=>{b.disabled=true;try{await save(b.dataset.city,b.dataset.uf,b.dataset.status)}catch(e){app.querySelector('#cities-error').textContent=e.message;b.disabled=false}});
  app.querySelector('#cities-add').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target);try{await save(f.get('city'),f.get('uf'),'observing')}catch(e){app.querySelector('#cities-error').textContent=e.message}};
 }catch(e){app.innerHTML=`<section><h1>Expansão por cidades</h1><p class="error">${esc(e.message)}</p><button class="btn secondary" id="cities-back">Voltar</button></section>`;app.querySelector('#cities-back').onclick=onBack}
}
